<script>document.addEventListener('DOMContentLoaded',()=>{const manager=document.getElementById('manager-select'),email=document.getElementById('manager-email');const syncManager=()=>{const option=manager?.options[manager.selectedIndex];if(email)email.value=option?.dataset.email||''};manager?.addEventListener('change',syncManager);syncManager();document.querySelectorAll('[data-phone-group]').forEach(group=>{const select=group.querySelector('[data-phone-select]'),flag=group.querySelector('[data-phone-flag]'),code=group.querySelector('[data-phone-code]');const sync=()=>{const option=select.options[select.selectedIndex],value=option?.value||'';code.textContent=value;flag.classList.toggle('saudi',value==='+966');flag.textContent=value==='+966'?'':(option?.dataset.flag||'🌐')};select.addEventListener('change',sync);sync()});const salary=[...document.querySelectorAll('.salary-component')],total=document.getElementById('total-salary');const sum=()=>{const value=salary.reduce((s,input)=>s+(parseFloat(input.value)||0),0);total.textContent=value.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})};salary.forEach(input=>input.addEventListener('input',sum));sum();document.querySelectorAll('[data-reference-mirror]').forEach(mirror=>{const source=document.querySelector(`[data-reference-source="${mirror.dataset.referenceMirror}"]`);if(!source)return;const sync=()=>mirror.value=source.value;source.addEventListener('input',sync);sync()})});</script>
